def fibonacci(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        a, b = 0, 1
        for _ in range(2, n + 1):
            a, b = b, a + b
        return b

fib_numbers = [fibonacci(i) for i in range(21)]
print("Fibonacci numbers F_0 to F_20:")
print(fib_numbers)

